//! Readers for index.txt, project.txt and lock.txt.
use crate::config;
use crate::versions::{is_name, Constraint, Version};
use std::collections::{BTreeMap, BTreeSet};

#[derive(Clone)]
pub struct Need {
    pub dep: String,
    pub constraint: Constraint,
    pub feats: Vec<String>,
    pub gate: Option<String>,
}

pub struct Package {
    pub name: String,
    pub version: Version,
    pub needs: Vec<Need>,
    pub breaks: Vec<(String, Constraint)>,
    pub features: Vec<String>,
    pub yanked: bool,
}

impl Package {
    pub fn active_needs(&self, enabled: &BTreeSet<String>) -> Vec<Need> {
        self.needs.iter().filter(|n| n.gate.as_ref().map_or(true, |g| enabled.contains(g))).cloned().collect()
    }
}

pub struct Index {
    pub pkgs: Vec<Package>,
    pub by_name: BTreeMap<String, Vec<usize>>, // newest version first
}

impl Index {
    pub fn versions(&self, name: &str) -> Vec<usize> {
        self.by_name.get(name).cloned().unwrap_or_default()
    }

    pub fn find(&self, name: &str, v: &Version) -> Option<usize> {
        self.by_name.get(name)?.iter().copied().find(|&i| self.pkgs[i].version == *v)
    }
}

fn err<T>(file: &str, n: usize, msg: &str) -> Result<T, String> {
    Err(format!("{}:{}: {}", file, n, msg))
}

fn words(line: &str) -> Vec<&str> {
    line.split('#').next().unwrap_or("").split_whitespace().collect()
}

fn features_of(tokens: &[&str], file: &str, n: usize) -> Result<Vec<String>, String> {
    let mut set = BTreeSet::new();
    for t in tokens {
        let ok = t.starts_with('+') && is_name(&t[1..]);
        if !ok {
            return err(file, n, &format!("bad name '{}'", t.trim_start_matches('+')));
        }
        set.insert(t[1..].to_string());
    }
    Ok(set.into_iter().collect())
}

/// needs NAME CONSTRAINT [+FEATURE...] [if FEATURE]
fn need_line(w: &[&str], n: usize) -> Result<Need, String> {
    let mut w = w.to_vec();
    let mut gate = None;
    if config::FEATURES && w.len() >= 3 && w[w.len() - 2] == "if" {
        gate = Some(w[w.len() - 1].to_string());
        w.truncate(w.len() - 2);
    }
    if w.len() < 3 || (!config::FEATURES && w.len() != 3) {
        return err("index.txt", n, "bad line");
    }
    let mut names = vec![w[1].to_string()];
    if let Some(g) = &gate {
        names.push(g.clone());
    }
    for name in names {
        if !is_name(&name) {
            return err("index.txt", n, &format!("bad name '{}'", name));
        }
    }
    let constraint = match Constraint::parse(w[2]) {
        Some(c) => c,
        None => return err("index.txt", n, &format!("bad constraint '{}'", w[2])),
    };
    let feats = features_of(&w[3..], "index.txt", n)?;
    Ok(Need { dep: w[1].to_string(), constraint, feats, gate })
}

pub fn read_index(text: &str) -> Result<Index, String> {
    let mut all: Vec<Package> = Vec::new();
    for (i, line) in text.split('\n').enumerate() {
        let n = i + 1;
        let w = words(line);
        if w.is_empty() {
            continue;
        }
        let d = w[0];
        if d == "pkg" {
            if w.len() != 3 {
                return err("index.txt", n, "bad line");
            }
            if !is_name(w[1]) {
                return err("index.txt", n, &format!("bad name '{}'", w[1]));
            }
            let ver = match Version::parse(w[2]) {
                Some(v) => v,
                None => return err("index.txt", n, &format!("bad version '{}'", w[2])),
            };
            if all.iter().any(|p| p.name == w[1] && p.version == ver) {
                return err("index.txt", n, &format!("duplicate package {} {}", w[1], w[2]));
            }
            all.push(Package { name: w[1].to_string(), version: ver, needs: vec![], breaks: vec![], features: vec![], yanked: false });
            continue;
        }
        let mut known = vec!["needs", "yanked"];
        if config::BREAKS {
            known.push("breaks");
        }
        if config::FEATURES {
            known.push("feature");
        }
        if !known.contains(&d) {
            return err("index.txt", n, &format!("unknown directive '{}'", d));
        }
        let cur = match all.last_mut() {
            Some(c) => c,
            None => return err("index.txt", n, &format!("'{}' outside a package block", d)),
        };
        match d {
            "yanked" => {
                if w.len() != 1 {
                    return err("index.txt", n, "bad line");
                }
                cur.yanked = true;
            }
            "feature" => {
                if w.len() != 2 {
                    return err("index.txt", n, "bad line");
                }
                if !is_name(w[1]) {
                    return err("index.txt", n, &format!("bad name '{}'", w[1]));
                }
                if cur.features.iter().any(|f| f == w[1]) {
                    return err("index.txt", n, &format!("duplicate feature '{}'", w[1]));
                }
                cur.features.push(w[1].to_string());
            }
            "breaks" => {
                if w.len() != 3 {
                    return err("index.txt", n, "bad line");
                }
                if !is_name(w[1]) {
                    return err("index.txt", n, &format!("bad name '{}'", w[1]));
                }
                match Constraint::parse(w[2]) {
                    Some(c) => cur.breaks.push((w[1].to_string(), c)),
                    None => return err("index.txt", n, &format!("bad constraint '{}'", w[2])),
                }
            }
            _ => {
                let need = need_line(&w, n)?;
                if let Some(g) = &need.gate {
                    if !cur.features.contains(g) {
                        return err("index.txt", n, &format!("undeclared feature '{}'", g));
                    }
                }
                cur.needs.push(need);
            }
        }
    }
    let mut by_name: BTreeMap<String, Vec<usize>> = BTreeMap::new();
    for (i, p) in all.iter().enumerate() {
        by_name.entry(p.name.clone()).or_default().push(i);
    }
    for list in by_name.values_mut() {
        list.sort_by(|a, b| all[*b].version.key().cmp(&all[*a].version.key()));
    }
    Ok(Index { pkgs: all, by_name })
}

pub type Want = (String, Constraint, Vec<String>);

pub fn read_project(text: &str) -> Result<Vec<Want>, String> {
    let mut wants = Vec::new();
    for (i, line) in text.split('\n').enumerate() {
        let n = i + 1;
        let w = words(line);
        if w.is_empty() {
            continue;
        }
        if w[0] != "want" {
            return err("project.txt", n, &format!("unknown directive '{}'", w[0]));
        }
        if w.len() < 3 || (!config::FEATURES && w.len() != 3) {
            return err("project.txt", n, "bad line");
        }
        if !is_name(w[1]) {
            return err("project.txt", n, &format!("bad name '{}'", w[1]));
        }
        let c = match Constraint::parse(w[2]) {
            Some(c) => c,
            None => return err("project.txt", n, &format!("bad constraint '{}'", w[2])),
        };
        wants.push((w[1].to_string(), c, features_of(&w[3..], "project.txt", n)?));
    }
    Ok(wants)
}

pub type Lock = BTreeMap<String, (Version, BTreeSet<String>)>;

pub fn read_lock(text: &str) -> Result<Lock, String> {
    let mut out = Lock::new();
    for (i, line) in text.split('\n').enumerate() {
        let n = i + 1;
        let w = words(line);
        if w.is_empty() {
            continue;
        }
        if (w.len() != 2 && w.len() != 3) || (w.len() == 3 && !config::FEATURES) {
            return err("lock.txt", n, "bad line");
        }
        if !is_name(w[0]) {
            return err("lock.txt", n, &format!("bad name '{}'", w[0]));
        }
        let ver = match Version::parse(w[1]) {
            Some(v) => v,
            None => return err("lock.txt", n, &format!("bad version '{}'", w[1])),
        };
        let plus: Vec<String> = if w.len() == 3 { w[2].split(',').map(|f| format!("+{}", f)).collect() } else { vec![] };
        let refs: Vec<&str> = plus.iter().map(|s| s.as_str()).collect();
        let feats = features_of(&refs, "lock.txt", n)?;
        if out.contains_key(w[0]) {
            return err("lock.txt", n, &format!("duplicate package '{}'", w[0]));
        }
        out.insert(w[0].to_string(), (ver, feats.into_iter().collect()));
    }
    Ok(out)
}

solution.src/main.rs:
//! Command line: lock, upgrade, tree, check.
mod checker;
mod config;
mod files;
mod solver;
mod versions;

use files::{read_index, read_lock, read_project, Index, Lock, Want};
use solver::{Outcome, Solver};
use std::collections::BTreeMap;
use versions::Version;

fn read(path: &str) -> Option<String> {
    std::fs::read_to_string(path).ok()
}

fn fail(msg: &str) -> i32 {
    println!("error: {}", msg);
    1
}

#[derive(PartialEq)]
enum LockMode {
    None,
    Optional,
    Required,
}

fn load(mode: LockMode) -> Result<(Index, Vec<Want>, Option<Lock>), String> {
    let text = read("index.txt").ok_or("cannot read index.txt")?;
    let index = read_index(&text)?;
    let text = read("project.txt").ok_or("cannot read project.txt")?;
    let wants = read_project(&text)?;
    let mut lock = None;
    if mode != LockMode::None {
        match read("lock.txt") {
            None => {
                if mode == LockMode::Required {
                    return Err("cannot read lock.txt".to_string());
                }
            }
            Some(t) => lock = Some(read_lock(&t)?),
        }
    }
    Ok((index, wants, lock))
}

fn resolve(index: &Index, wants: &[Want], oldest: bool, prefer: &BTreeMap<String, Version>) -> i32 {
    let mut s = Solver::new(index, wants, oldest, prefer);
    let st = match s.run() {
        Outcome::Limit => return fail("search limit reached"),
        Outcome::Dead => return fail(&s.dead.clone().unwrap_or_default()),
        Outcome::Solved(st) => st,
    };
    let mut lines = Vec::new();
    for (name, &pi) in &st.chosen {
        let p = &index.pkgs[pi];
        let feats = st.feats.get(name).cloned().unwrap_or_default();
        let mut l = format!("{} {}", name, p.version.text);
        if !feats.is_empty() {
            l.push(' ');
            l.push_str(&checker::fmt_feats(&feats));
        }
        lines.push(l);
    }
    let body: String = lines.iter().map(|l| format!("{}\n", l)).collect();
    let _ = std::fs::write("lock.txt", body);
    for l in &lines {
        println!("{}", l);
    }
    println!("locked {} packages", lines.len());
    0
}

fn cmd_lock(args: &[String]) -> Result<i32, String> {
    let (mut oldest, mut fresh) = (false, false);
    for a in args {
        if a == "--oldest" && config::OLDEST_OPT {
            oldest = true;
        } else if a == "--fresh" && config::STICKY {
            fresh = true;
        } else if a.starts_with('-') {
            return Ok(fail(&format!("unknown option '{}'", a)));
        } else {
            return Ok(fail(&format!("usage: {} lock [OPTION...]", config::TOOL)));
        }
    }
    let mode = if config::STICKY && !fresh { LockMode::Optional } else { LockMode::None };
    let (index, wants, lock) = load(mode)?;
    let mut prefer = BTreeMap::new();
    if let Some(l) = lock {
        for (n, (v, _)) in l {
            prefer.insert(n, v);
        }
    }
    Ok(resolve(&index, &wants, oldest, &prefer))
}

fn cmd_upgrade(args: &[String]) -> Result<i32, String> {
    if args.is_empty() {
        return Ok(fail(&format!("usage: {} upgrade NAME...", config::TOOL)));
    }
    let (index, wants, lock) = load(LockMode::Required)?;
    let lock = lock.unwrap();
    for n in args {
        if !lock.contains_key(n) {
            return Ok(fail(&format!("{} is not locked", n)));
        }
    }
    let mut prefer = BTreeMap::new();
    for (n, (v, _)) in lock {
        if !args.contains(&n) {
            prefer.insert(n, v);
        }
    }
    Ok(resolve(&index, &wants, false, &prefer))
}

fn cmd_tree(args: &[String]) -> Result<i32, String> {
    if !args.is_empty() {
        return Ok(fail(&format!("usage: {} tree", config::TOOL)));
    }
    let (index, wants, lock) = load(LockMode::Required)?;
    for l in checker::tree(&index, &wants, &lock.unwrap()) {
        println!("{}", l);
    }
    Ok(0)
}

fn cmd_check(args: &[String]) -> Result<i32, String> {
    if !args.is_empty() {
        return Ok(fail(&format!("usage: {} check", config::TOOL)));
    }
    let (index, wants, lock) = load(LockMode::Required)?;
    let lock = lock.unwrap();
    let problems = checker::check(&index, &wants, &lock);
    for p in &problems {
        println!("{}", p);
    }
    if !problems.is_empty() {
        println!("FAILED: {} problems", problems.len());
        return Ok(1);
    }
    println!("ok: {} packages", lock.len());
    Ok(0)
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let code = if args.is_empty() {
        fail(&format!("usage: {} COMMAND [ARGS]", config::TOOL))
    } else {
        let rest = &args[1..];
        let result = match args[0].as_str() {
            "lock" => cmd_lock(rest),
            "tree" => cmd_tree(rest),
            "check" => cmd_check(rest),
            "upgrade" if config::STICKY => cmd_upgrade(rest),
            other => Ok(fail(&format!("unknown command '{}'", other))),
        };
        match result {
            Ok(c) => c,
            Err(e) => fail(&e),
        }
    };
    std::process::exit(code);
}

solution.src/solver.rs:
//! The resolver: a depth-first search with chronological backtracking over a queue of package names.
use crate::config;
use crate::files::{Index, Need, Want};
use crate::versions::{Constraint, Version};
use std::collections::{BTreeMap, BTreeSet, VecDeque};

#[derive(Clone, Default)]
pub struct State {
    pub chosen: BTreeMap<String, usize>,
    pub reqs: BTreeMap<String, Vec<(Constraint, String)>>,
    pub feats: BTreeMap<String, BTreeSet<String>>,
    pub queue: Vec<String>,
    pub queued: BTreeSet<String>,
    pub breaks: Vec<(String, Constraint)>,
}

pub struct Solver<'a> {
    index: &'a Index,
    wants: &'a [Want],
    oldest: bool,
    prefer: &'a BTreeMap<String, Version>,
    attempts: i64,
    pub dead: Option<String>,
}

pub enum Outcome {
    Solved(State),
    Dead,
    Limit,
}

impl<'a> Solver<'a> {
    pub fn new(index: &'a Index, wants: &'a [Want], oldest: bool, prefer: &'a BTreeMap<String, Version>) -> Solver<'a> {
        Solver { index, wants, oldest, prefer, attempts: 0, dead: None }
    }

    /// Process (owner, need) pairs first in, first out; false if a chosen package cannot accept one.
    fn apply(&self, st: &mut State, mut work: VecDeque<(usize, Need)>) -> bool {
        while let Some((owner, need)) = work.pop_front() {
            let op = &self.index.pkgs[owner];
            let who = format!("{} {}", op.name, op.version.text);
            st.reqs.entry(need.dep.clone()).or_default().push((need.constraint.clone(), who));
            let have = st.feats.entry(need.dep.clone()).or_default();
            let new: Vec<String> = need.feats.iter().filter(|f| !have.contains(*f)).cloned().collect();
            for f in &new {
                have.insert(f.clone());
            }
            if let Some(&di) = st.chosen.get(&need.dep) {
                let dp = &self.index.pkgs[di];
                if !need.constraint.allows(&dp.version) {
                    return false;
                }
                if new.iter().any(|f| !dp.features.contains(f)) {
                    return false;
                }
                for n in &dp.needs {
                    if n.gate.as_ref().map_or(false, |g| new.contains(g)) {
                        work.push_back((di, n.clone()));
                    }
                }
            } else if !st.queued.contains(&need.dep) {
                st.queued.insert(need.dep.clone());
                st.queue.push(need.dep.clone());
            }
        }
        true
    }

    fn candidates(&self, st: &State, name: &str) -> Vec<usize> {
        let cons: Vec<&Constraint> = st.reqs.get(name).map(|v| v.iter().map(|(c, _)| c).collect()).unwrap_or_default();
        let locked = self.prefer.get(name);
        let wanted_feats = st.feats.get(name);
        let mut out = Vec::new();
        for i in self.index.versions(name) {
            let p = &self.index.pkgs[i];
            if p.yanked && !locked.map_or(false, |l| *l == p.version) {
                continue;
            }
            if !cons.iter().all(|c| c.allows(&p.version)) {
                continue;
            }
            if st.breaks.iter().any(|(t, c)| t == name && c.allows(&p.version)) {
                continue;
            }
            if let Some(fs) = wanted_feats {
                if fs.iter().any(|f| !p.features.contains(f)) {
                    continue;
                }
            }
            out.push(i);
        }
        if self.oldest {
            out.reverse();
        }
        if let Some(l) = locked {
            // stable: only the locked version moves to the front
            let (mut first, rest): (Vec<usize>, Vec<usize>) = out.into_iter().partition(|&i| self.index.pkgs[i].version == *l);
            first.extend(rest);
            out = first;
        }
        out
    }

    fn choose(&self, st: &mut State, pi: usize) -> bool {
        let p = &self.index.pkgs[pi];
        st.chosen.insert(p.name.clone(), pi);
        st.feats.entry(p.name.clone()).or_default();
        for (target, c) in &p.breaks {
            if let Some(&ti) = st.chosen.get(target) {
                if c.allows(&self.index.pkgs[ti].version) {
                    return false;
                }
            }
            st.breaks.push((target.clone(), c.clone()));
        }
        let enabled = st.feats[&p.name].clone();
        let work: VecDeque<(usize, Need)> = p.active_needs(&enabled).into_iter().map(|n| (pi, n)).collect();
        self.apply(st, work)
    }

    fn solve(&mut self, st: &State) -> Result<Option<State>, ()> {
        if st.queue.is_empty() {
            return Ok(Some(st.clone()));
        }
        let name = st.queue[0].clone();
        if self.index.versions(&name).is_empty() {
            if self.dead.is_none() {
                self.dead = Some(format!("unknown package {}", name));
            }
            return Ok(None);
        }
        for pi in self.candidates(st, &name) {
            self.attempts += 1;
            if self.attempts > config::LIMIT {
                return Err(());
            }
            let mut s2 = st.clone();
            s2.queue.remove(0);
            if self.choose(&mut s2, pi) {
                if let Some(r) = self.solve(&s2)? {
                    return Ok(Some(r));
                }
            }
        }
        if self.dead.is_none() {
            let needs: Vec<String> = st.reqs.get(&name).map(|v| v.iter().map(|(c, who)| format!("{} ({})", c.text, who)).collect()).unwrap_or_default();
            self.dead = Some(format!("cannot resolve {}: needs {}", name, needs.join(", ")));
        }
        Ok(None)
    }

    pub fn run(&mut self) -> Outcome {
        let mut st = State::default();
        for (name, cons, feats) in self.wants {
            st.reqs.entry(name.clone()).or_default().push((cons.clone(), "root".to_string()));
            let e = st.feats.entry(name.clone()).or_default();
            for f in feats {
                e.insert(f.clone());
            }
            if !st.queued.contains(name) {
                st.queued.insert(name.clone());
                st.queue.push(name.clone());
            }
        }
        match self.solve(&st) {
            Ok(Some(s)) => Outcome::Solved(s),
            Ok(None) => Outcome::Dead,
            Err(()) => Outcome::Limit,
        }
    }
}

